package com.quiz;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

/**
 * Manages player scores and leaderboard.
 * Contains ZERO pre-loaded data - only records scores generated by real users.
 */
public class ScoreService {
    private final List<ScoreRecord> scores = new CopyOnWriteArrayList<>();
    private final Path storageFile;

    public ScoreService() {
        this.storageFile = Paths.get("data", "scores.txt");
        // Strictly NO pre-loaded/hardcoded scores - completely clean start
        loadFromFile();
    }

    public synchronized void addScore(ScoreRecord record) {
        scores.add(record);
        saveToFile();
    }

    public List<ScoreRecord> getTopScores(int limit) {
        List<ScoreRecord> sorted = new ArrayList<>(scores);
        Collections.sort(sorted);
        if (limit > 0 && limit < sorted.size()) {
            return sorted.subList(0, limit);
        }
        return sorted;
    }

    public List<ScoreRecord> getUserScores(String playerName) {
        if (playerName == null) return Collections.emptyList();
        List<ScoreRecord> userList = new ArrayList<>();
        for (ScoreRecord r : scores) {
            if (r.getPlayerName().equalsIgnoreCase(playerName.trim())) {
                userList.add(r);
            }
        }
        return userList;
    }

    public String getLeaderboardJson(int limit) {
        List<ScoreRecord> top = getTopScores(limit);
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < top.size(); i++) {
            sb.append(top.get(i).toJson());
            if (i < top.size() - 1) sb.append(",");
        }
        sb.append("]");
        return sb.toString();
    }

    public String getUserHistoryJson(String playerName) {
        List<ScoreRecord> userList = getUserScores(playerName);
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < userList.size(); i++) {
            sb.append(userList.get(i).toJson());
            if (i < userList.size() - 1) sb.append(",");
        }
        sb.append("]");
        return sb.toString();
    }

    public synchronized void clearAllScores() {
        scores.clear();
        saveToFile();
    }

    private void saveToFile() {
        try {
            Path parent = storageFile.getParent();
            if (parent != null && !Files.exists(parent)) {
                Files.createDirectories(parent);
            }
            List<String> lines = new ArrayList<>();
            for (ScoreRecord r : scores) {
                // playerName|category|score|correctAnswers|totalQuestions|timeTakenSeconds
                lines.add(String.join("|",
                    r.getPlayerName(),
                    r.getCategory(),
                    String.valueOf(r.getScore()),
                    String.valueOf(r.getCorrectAnswers()),
                    String.valueOf(r.getTotalQuestions()),
                    String.valueOf(r.getTimeTakenSeconds())
                ));
            }
            Files.write(storageFile, lines, StandardCharsets.UTF_8);
        } catch (IOException ignored) {}
    }

    private void loadFromFile() {
        try {
            if (Files.exists(storageFile)) {
                List<String> lines = Files.readAllLines(storageFile, StandardCharsets.UTF_8);
                for (String line : lines) {
                    String[] parts = line.split("\\|");
                    if (parts.length >= 6) {
                        try {
                            String name = parts[0];
                            String cat = parts[1];
                            int score = Integer.parseInt(parts[2]);
                            int correct = Integer.parseInt(parts[3]);
                            int total = Integer.parseInt(parts[4]);
                            int time = Integer.parseInt(parts[5]);
                            scores.add(new ScoreRecord(name, cat, score, correct, total, time));
                        } catch (NumberFormatException ignored) {}
                    }
                }
            }
        } catch (IOException ignored) {}
    }
}
